/**
 * Storage object-key helpers shared by the server storage adapter and tests.
 * Keys are always generated by the application; user supplied names never
 * become object keys.
 */

export const MUSIC_PREFIX = "music/";
export const ARTWORK_PREFIX = "artwork/";

/**
 * Prefixes this application is allowed to write to and delete from. The
 * legacy prefixes keep records created by earlier versions of Sidewave
 * manageable after the move to Neon Object Storage.
 */
export const MANAGED_PREFIXES = [
  MUSIC_PREFIX,
  ARTWORK_PREFIX,
  "audio/",
  "covers/",
] as const;

export function isManagedKey(key: unknown): key is string {
  return (
    typeof key === "string" &&
    key.length > 0 &&
    key.length <= 512 &&
    !key.includes("..") &&
    !key.includes("\\") &&
    !/[\u0000-\u001f]/.test(key) &&
    MANAGED_PREFIXES.some((prefix) => key.startsWith(prefix))
  );
}

export function musicObjectKey() {
  return `${MUSIC_PREFIX}${crypto.randomUUID()}.mp3`;
}

export function artworkObjectKey() {
  return `${ARTWORK_PREFIX}${crypto.randomUUID()}.webp`;
}

/**
 * Raw artwork uploaded by the browser before the server validates and
 * re-encodes it. The `.source` suffix keeps it distinct from public covers.
 */
export function artworkSourceKey() {
  return `${ARTWORK_PREFIX}${crypto.randomUUID()}.source`;
}
